'use client';
import dynamic from 'next/dynamic';
import { LOCATION_TYPE_ICONS } from '../../src/lib/location-type-icons';
import { Suspense, useMemo, useState } from 'react';
import { useSearchParams } from 'next/navigation';
import { MonitorWorkspace } from '../../src/app/admin/logistics/shipments/monitoring_v2/workspace';
import { normalizeFleet } from '../../src/app/admin/logistics/shipments/monitoring_v2/model';
import type { Shipment, VehicleActivity } from '../../src/lib/types';
import { Box, LayoutDashboard, CalendarDays, Package, MapPin, Route, MessageSquare, Users, Truck, ChartNoAxesColumn, Settings, CreditCard, ChevronDown } from 'lucide-react';
function Preview(){
 const query=useSearchParams();const catalog=query.get('catalog')==='1';const [sampleType,setSampleType]=useState('warehouse');const count=Math.min(2000,Math.max(0,Number(query.get('count') ?? 105)));const [updated,setUpdated]=useState(()=>Date.now());
 const rows=useMemo(()=>{
 const catalogEntry=LOCATION_TYPE_ICONS.find(entry=>entry.value===sampleType);
 const locs=catalog?[[catalogEntry?.label || 'Fallback location', 'Location type verification',sampleType]]:[['Midrand DC','24 Impala Rd, Midrand','warehouse'],['Ultra Fuel Midrand','R562 Service Road','fuel-station-2'],['Tembisa Yard','Olifantsfontein Rd','warehouse'],['Pretoria Hub','De Waal St, Pretoria','warehouse']];
 return Array.from({length:catalog?1:count},(_,i):VehicleActivity=>{
 const loc=catalog?0:Math.floor(Math.max(0,i-68)/6)%4;
 const status=catalog?'at_location':i<68?'in_transit':i<92?'at_location':i<101?'standby':'unknown';
 const ago=i<68?30:i<71?112-(i-68)*20:status==='standby'?3200:15+(i%5)*7;
 return {activity_id:`a-${i}`,vehicle:{vehicle_id:`v-${i}`,plate_number:i===0?'GP 4821':i===68?'GP 3156':`GP ${6000+i}`,last_driver:{name:'A. Ndlovu',telephone:'+27 82 456 7890'}},driver:{name:'A. Ndlovu',telephone:'+27 82 456 7890'},monitoring:{status,since_at:new Date(updated-ago*60000).toISOString(),location:status==='at_location'||status==='standby'?{location_id:`loc-${loc}`,name:locs[loc][0],full_address:locs[loc][1],expected_waiting_time:status==='standby'?null:60,type:{icon:locs[loc][2]}}:null},event_type:status==='in_transit'?'exited_location':'entered_location',occurred_at:new Date(updated-30000).toISOString(),speed_kph:status==='in_transit'?i===1?96:i===2?92:42:0,speed_limit_kph:80,latitude:null,longitude:null,shipment:i===0?{shipment_id:'sh-2048',merchant_order_ref:'SH-2048',status:'in_transit'}:null,location:status==='at_location'?{location_id:`loc-${loc}`,name:locs[loc][0]}:null};});
 },[count,updated,catalog,sampleType]);
 const shipment:Shipment={shipment_id:'sh-2048',merchant_order_ref:'SH-2048',status:'in_transit',vehicle:{vehicle_id:'v-0',plate_number:'GP 4821'},pickup_location:{location_id:'loc-0',name:'Midrand DC'} as Shipment['pickup_location'],dropoff_location:{location_id:'loc-3',name:'Pretoria Hub'} as Shipment['dropoff_location'],location_visit_intervals:{pickup:{entered_at:new Date(updated-135*60000).toISOString(),exited_at:new Date(updated-30*60000).toISOString()}},stops:[]};
 return <div style={{display:'flex',minHeight:'100vh',background:'white'}}><aside className="preview-sidebar" style={{width:240,flexShrink:0,borderRight:'1px solid #e9edf3',padding:'18px 14px',color:'#111827',fontFamily:'Arial'}}><div style={{display:'flex',gap:10,alignItems:'center',fontWeight:700,marginBottom:18}}><Box size={28}/>Spaces Digital</div><div style={{border:'1px solid #e5eaf2',borderRadius:8,padding:12,fontSize:12,fontWeight:700,display:'flex',justifyContent:'space-between'}}>SESFIGILE LOGISTICS <ChevronDown size={15}/></div>{[[LayoutDashboard,'Dashboard'],[CalendarDays,'Runs Schedule'],[Package,'Shipments'],[MapPin,'Locations'],[Route,'Routes'],[MessageSquare,'Messages'],[Box,'3D Monitor'],[Users,'Drivers'],[Truck,'Vehicles'],[ChartNoAxesColumn,'Analytics'],[Settings,'Settings'],[CreditCard,'Billing']].map(([Icon,label])=>{const I=Icon as typeof Box;return <div key={String(label)} style={{display:'flex',gap:13,alignItems:'center',padding:'13px 10px',marginTop:3,borderRadius:8,fontSize:14,background:label==='3D Monitor'?'#e7efff':'transparent',color:label==='3D Monitor'?'#1463ff':'#111827'}}><I size={18}/>{String(label)}</div>;})}<small style={{display:'block',marginTop:40,color:'#6b7280'}}>Development fixture · sample data</small></aside><div style={{flex:1,minWidth:0}}>{catalog && <label style={{display:'block',padding:12}}>Preview location type <select aria-label="Preview location type" value={sampleType} onChange={event=>setSampleType(event.target.value)}>{LOCATION_TYPE_ICONS.map(entry=><option key={entry.value} value={entry.value}>{entry.label}</option>)}<option value="unsupported-type">Unsupported type fallback</option><option value="">Missing type fallback</option></select></label>}<MonitorWorkspace fleet={normalizeFleet(rows)} events={rows.slice(0,6)} loading={false} error={query.get('error')?'Fleet refresh failed. Showing the last successful snapshot.':null} eventError={null} updated={updated} refresh={()=>setUpdated(Date.now())} sample fixtureShipment={shipment}/></div><style>{'@media(max-width:760px){.preview-sidebar{display:none}}'}</style></div>;
}
const ClientPreview=dynamic(()=>Promise.resolve(Preview),{ssr:false});
export default function MonitoringPreview(){return <Suspense><ClientPreview/></Suspense>;}
